package linkedlist

import "errors"

// Element is a node in the singly linked list.
type Element struct {
	data int
	next *Element
}

// List is a singly linked list of song IDs.
type List struct {
	head *Element
	tail *Element
	size int
}

// New creates a new List from the given elements.
func New(elements []int) *List {
	list := &List{}
	for _, element := range elements {
		list.Push(element)
	}
	return list
}

// Size returns the number of elements in the list.
func (l *List) Size() int {
	return l.size
}

// Push appends the element to the end of the list.
func (l *List) Push(element int) {
	e := &Element{data: element}
	if l.tail != nil {
		l.tail.next = e
	} else {
		l.head = e
	}
	l.tail = e
	l.size++
}

// Pop removes and returns the last element of the list.
// It returns an error if the list is empty.
func (l *List) Pop() (int, error) {
	if l.tail == nil {
		return 0, errors.New("pop from empty list")
	}
	data := l.tail.data
	if l.head == l.tail {
		l.head = nil
		l.tail = nil
	} else {
		// Walk to the element before the tail to unlink it.
		prev := l.head
		for prev.next != l.tail {
			prev = prev.next
		}
		prev.next = nil
		l.tail = prev
	}
	l.size--
	return data, nil
}

// Array returns the elements of the list in order.
func (l *List) Array() []int {
	array := make([]int, 0, l.size)
	for e := l.head; e != nil; e = e.next {
		array = append(array, e.data)
	}
	return array
}

// Reverse returns a new List with the elements in reverse order.
func (l *List) Reverse() *List {
	reversed := &List{}
	for e := l.head; e != nil; e = e.next {
		reversed.Push(e.data)
	}
	return reversed
}

